custom.expression:
let clock = fract(t / 3600.0) * 6.283185;
let q = rotate(p, bank_angle * sin(clock * 31.0));
let h = 0.04 + 0.023 * sin(clock * 23.0);
let y = q.y - h;
let dusk = exp(-5.2 * abs(y));
let vapor = cloud(vec2<f32>(q.x * 3.4 + 0.7 * sin(clock * 13.0), y * 15.0));
let sky = mix(c2 * 0.65, c3 * 0.91, dusk);
let clouds = smoothstep(0.42, 0.76, vapor) * smoothstep(0.015, 0.15, y);
let air = mix(sky, mix(c2, c4, dusk), clouds * 0.42);

let flanks = smoothstep(0.08, 0.72, abs(q.x));
let ridgeFar = flanks * (0.04 + 0.15 * fbm(vec2<f32>(q.x * 4.0 + 0.45 * sin(clock * 17.0), 6.0)));
let ridgeNear = flanks * (0.014 + 0.077 * ridged(vec2<f32>(q.x * 7.0 + 0.9 * sin(clock * 17.0), 3.0)));
let hills = mix(air, mix(c2 * 0.53, c3 * 0.56, dusk * 0.5), fill(y - ridgeFar));
let view = mix(hills, mix(c1, c2 * 0.49, dusk * 0.65), fill(y - ridgeNear));

let z = max(-y, 0.0);
let center = 0.11 * z * sin(clock * 19.0);
let x = abs(q.x - center);
let width = 0.007 + z * 0.61;
let reveal = smoothstep(0.005, 0.063, z);
let ground = mix(c1 * 1.27, c2 * 0.52, exp(-6.0 * z));
let strip = mix(c1 * 1.85, c2 * 0.66, exp(-4.0 * z));
let pavement = mix(view, mix(ground, strip, fill(x - width)), reveal);
let depth = 0.62 / (z + 0.068);
let phase = fract(t * round(approach_speed * 3600.0) / 3600.0);
let dash = abs(fract(depth + phase) - 0.5);
let paint = (1.0 - smoothstep(0.13, 0.23, dash)) * fill(x - (0.001 + 0.009 * z));
let lamp = abs(x - width);
let bead = 1.0 - smoothstep(0.035, 0.15, abs(fract((depth + phase) * 2.0) - 0.5));
let edge = c4 * (0.21 * halo(lamp, 0.016) + 0.95 * halo(lamp, 0.007) * bead);
let zone = reveal * smoothstep(0.045, 0.15, z);

let u = vec2<f32>(abs(p.x), p.y - 0.09);
let wing = sd_segment(u, vec2<f32>(0.029, 0.0), vec2<f32>(0.097, 0.0));
let tip = sd_segment(u, vec2<f32>(0.029, -0.013), vec2<f32>(0.029, 0.0));
let sight = min(min(wing, tip), abs(length(u) - 0.010));
let ticks = sd_box(vec2<f32>(u.x - 0.145, abs(fract((u.y + 0.035) / 0.07) - 0.5) * 0.07), vec2<f32>(0.011, 0.001));
let ladder = halo(ticks, 0.004) * (1.0 - smoothstep(0.12, 0.21, abs(u.y)));
let hud = c5 * hud_glow * (0.8 * halo(sight, 0.005) + 0.29 * ladder);
let scene = pavement + zone * (edge + c4 * paint * 0.65) + hud;
return mix(bg, tonemap(scene), strength);
